		}
		if err := rows.Err(); err != nil {
			return err
		}

		countQuery := "SELECT COUNT(*) FROM ride_history"
		countSpan := d.startSQLSpan(ctx, countQuery)
		defer countSpan.End()
		return d.db.QueryRow(countQuery).Scan(&history.Total)
