		if err != nil {
			return err
		}
		defer rows.Close()
		for rows.Next() {
			e, err := scanRideHistory(rows)
			if err != nil {
				return err
			}
			history.Rides = append(history.Rides, *e)
		}
		if err := rows.Err(); err != nil {
			return err
		}

		countQuery := "SELECT COUNT(*) FROM ride_history"
		countSpan := d.startSQLSpan(ctx, countQuery)
		defer countSpan.End()
		return d.db.QueryRow(countQuery).Scan(&history.Total)
	})
	if err != nil {
		return nil, err
	}
	return history, nil
}

// CreateRideHistory stores a new ride without a driver and fare.
func (d *database) CreateRideHistory(ctx context.Context, req *CreateRideHistoryRequest) (*RideHistoryEntry, error) {
	requestTime := time.Now()
	if req.RequestTime != nil {
		requestTime = *req.RequestTime
	}
	requestTime = requestTime.UTC().Truncate(time.Millisecond)
	d.logger.For(ctx).Info("Creating ride history entry",
		zap.String("pickup", req.PickupName), zap.String("dropoff", req.DropoffName))

	var id int64
	err := d.rideHistoryRetry(func() error {
		query := "INSERT INTO ride_history (pickup_name, dropoff_name, request_time) VALUES (?, ?, ?)"
		span := d.startSQLSpan(ctx, query)
		defer span.End()

		res, err := d.db.Exec(query, req.PickupName, req.DropoffName, requestTime)
		if err != nil {
			return err
		}
		id, err = res.LastInsertId()
		return err
	})
	if err != nil {
		return nil, err
	}
	return &RideHistoryEntry{
		ID:          id,
		PickupName:  req.PickupName,
		DropoffName: req.DropoffName,
		RequestTime: requestTime,
	}, nil
}

// UpdateRideHistory records the driver plate and fare of an existing ride.
func (d *database) UpdateRideHistory(ctx context.Context, req *UpdateRideHistoryRequest) (*RideHistoryEntry, error) {
	d.logger.For(ctx).Info("Updating ride history entry",
		zap.Int64("ride_id", req.ID), zap.String("plate", req.DriverPlate))

	fare := math.Round(req.Fare*100) / 100
	var entry *RideHistoryEntry
	err := d.rideHistoryRetry(func() error {
		query := "UPDATE ride_history SET driver_plate = ?, fare = ? WHERE id = ?"
		span := d.startSQLSpan(ctx, query)
		defer span.End()

		if _, err := d.db.Exec(query, req.DriverPlate, fare, req.ID); err != nil {
			return err
		}

		// affected rows is 0 when the values didn't change, so check existence
		// by reading the row back
		selectQuery := "SELECT id, pickup_name, dropoff_name, request_time, driver_plate, fare " +
			"FROM ride_history WHERE id = ?"
		selectSpan := d.startSQLSpan(ctx, selectQuery)
		defer selectSpan.End()

		var err error
		entry, err = scanRideHistory(d.db.QueryRow(selectQuery, req.ID))
		if errors.Is(err, sql.ErrNoRows) {
			return errRideNotFound
		}
		return err
	})
	if err != nil {
		return nil, err
	}
	return entry, nil
}

type rowScanner interface {
	Scan(dest ...any) error
}

func scanRideHistory(row rowScanner) (*RideHistoryEntry, error) {
	var (
		e     RideHistoryEntry
		plate sql.NullString
		fare  sql.NullFloat64
	)
	if err := row.Scan(&e.ID, &e.PickupName, &e.DropoffName, &e.RequestTime, &plate, &fare); err != nil {
		return nil, err
	}
	if plate.Valid {
		e.DriverPlate = &plate.String
	}
	if fare.Valid {
		e.Fare = &fare.Float64
	}
	return &e, nil
}
