export type DriverAssignment = {
    plate: string,
    fare: number,
}

// The driver service announces a ride as, for example:
//   "Driver T712345C arriving in 12m34s. Fare: $18.85"
const DRIVER_ASSIGNMENT_REGEX = /Driver\s+(.+?)\s+arriving\s+in\s+.*?Fare:\s*\$(\d+(?:\.\d+)?)/;

export const parseDriverAssignment = (body: string): DriverAssignment | undefined => {
    const match = body.match(DRIVER_ASSIGNMENT_REGEX);
    if (!match) return;

    return {plate: match[1], fare: parseFloat(match[2])};
}

