import {useCallback, useEffect, useRef, useState} from "react";
import {apiGet, apiPatch, apiPostChecked} from "../services/http.ts";
import {RideHistory, RideHistoryEntry} from "../types/rideHistory.ts";
import {DriverAssignment} from "../utils/driverNotification.ts";

type TrackedRide = {
    // set once the ride-history entry has been created
    id?: number,
    // set once the driver notification has arrived
    assignment?: DriverAssignment,
}

export const useRideHistory = () => {
    const [history, setHistory] = useState<RideHistory>({rides: [], total: 0});
    const [error, setError] = useState<string | undefined>();
    // the driver notification and the creation of the entry race each other, so
    // track both per request
    const trackedRides = useRef(new Map<number, TrackedRide>());

    const refresh = useCallback(async () => {
        try {
            setHistory(await apiGet<RideHistory>('/ride-history'));
            setError(undefined);
        } catch (e) {
            console.error(e);
            setError('Could not load the ride history.');
        }
    }, []);

    useEffect(() => {
        refresh();
    }, [refresh]);

    const applyAssignment = useCallback(async (ride: TrackedRide) => {
        if (ride.id === undefined || !ride.assignment) return;

        try {
            await apiPatch<RideHistoryEntry>('/ride-history', {
                id: ride.id,
                driverPlate: ride.assignment.plate,
                fare: ride.assignment.fare,
            });
        } catch (e) {
            console.error(e);
            setError('Could not update the ride history.');
        }
        await refresh();
    }, [refresh]);

    // Creates the ride-history entry of a dispatched request.
    const addRide = useCallback(async (requestID: number, pickupName: string, dropoffName: string) => {
        const ride: TrackedRide = trackedRides.current.get(requestID) ?? {};
        trackedRides.current.set(requestID, ride);

        try {
            const entry = await apiPostChecked<RideHistoryEntry>('/ride-history', {
                pickupName,
                dropoffName,
                requestTime: new Date().toISOString(),
            });
            ride.id = entry.id;
        } catch (e) {
            console.error(e);
            setError('Could not save the ride to the ride history.');
            return;
        }

        if (ride.assignment) {
            await applyAssignment(ride);
        } else {
            await refresh();
        }
    }, [applyAssignment, refresh]);

    // Records the driver plate and fare of a request once a driver was found.
    const assignDriver = useCallback(async (requestID: number, assignment: DriverAssignment) => {
        const ride: TrackedRide = trackedRides.current.get(requestID) ?? {};
        trackedRides.current.set(requestID, ride);
        ride.assignment = assignment;

        await applyAssignment(ride);
    }, [applyAssignment]);

    return {history, error, addRide, assignDriver};
}
